const GLOSS={
 // фонетика и орфоэпия: составные термины — в начале, чтобы автоссылка находила их раньше общих («двойные согласные» раньше «согласный»)
 fonetika:{t:'Фонетика',d:'Раздел науки о языке, который изучает звуки речи, слоги и ударение.',ex:'звуки [а], [м\'], слоги ма-ма, ударение в слове ма́ма',cat:'Фонетика и орфоэпия',f:'фонетик(?:а|и|е|у|ой)',at:'zv1',see:['zvuk', 'grafika', 'slog']},
 grafika:{t:'Графика',d:'Раздел науки о языке, который изучает буквы и то, как ими обозначают звуки на письме.',ex:'мягкость [л\'] обозначает ь или гласная буква: лень, лёд',cat:'Фонетика и орфоэпия',f:'графика|графики|графике|графику|графикой',at:'zv1',see:['bukva', 'alfavit', 'fonetika']},
 alfavit:{t:'Алфавит',d:'Все буквы языка, расположенные в принятом порядке. В русском алфавите 33 буквы.',ex:'а, б, в, г, д, е, ё, ж, з …',cat:'Фонетика и орфоэпия',f:'алфавит(?:а|у|ом|е)?',at:'zv1',see:['bukva', 'grafika']},
 transkr:{t:'Транскрипция',d:'Запись слова так, как оно звучит: в квадратных скобках, мягкость — знаком \', ударение — знаком ́.',ex:'ёж [йо́ш], день [д\'е́н\']',cat:'Фонетика и орфоэпия',f:'транскрипци(?:я|и|ю|ей)',at:'zv5',see:['zvuk', 'fon_razb']},
 zvonk:{t:'Звонкий согласный',d:'Согласный, который произносится с голосом и шумом.',ex:'[б], [в], [г], [д], [ж], [з]; сонорные [л], [м], [н], [р], [й]',cat:'Фонетика и орфоэпия',f:'звонк(?:ий|ие|их|ого|ому|им|ими)',at:'zv3',see:['gluh', 'parn', 'soglasn']},
 gluh:{t:'Глухой согласный',d:'Согласный, который произносится одним шумом, без голоса.',ex:'[п], [ф], [к], [т], [ш], [с]; [х], [ц], [ч\'], [щ\']',cat:'Фонетика и орфоэпия',f:'глух(?:ой|ие|их|ого|ому|им|ими)',at:'zv3',see:['zvonk', 'parn', 'oglush']},
 parn:{t:'Парные и непарные согласные',d:'Парные — согласные, которые различаются только одним признаком (звонкостью-глухостью или твёрдостью-мягкостью): [б]–[п], [л]–[л\']. У непарных такой пары нет.',ex:'парные [д]–[т]; непарные по звонкости [л], [м], [ц], [ч\']',cat:'Фонетика и орфоэпия',f:'(?:не)?парн(?:ый|ые|ых|ого|ому|ым|ыми)',at:'zv3',see:['zvonk', 'gluh', 'tverd']},
 tverd:{t:'Твёрдый согласный',d:'Согласный, который произносится без подъёма средней части языка к нёбу. Всегда твёрдые: [ж], [ш], [ц].',ex:'[л] в слове лук; [ж] в слове жизнь',cat:'Фонетика и орфоэпия',f:'тв[её]рд(?:ый|ые|ых|ого|ому|ым|ыми)',at:'zv3',see:['myagk', 'parn', 'soglasn']},
 myagk:{t:'Мягкий согласный',d:'Согласный, который произносится с подъёмом средней части языка к нёбу; в транскрипции — знак \'. Всегда мягкие: [ч\'], [щ\'], [й\'].',ex:'[л\'] в слове люк; [ч\'] в слове час',cat:'Фонетика и орфоэпия',f:'мягк(?:ий|ие|их|ого|ому|им|ими)(?!\\s+знак)',at:'zv3',see:['tverd', 'parn', 'soglasn']},
 sonor:{t:'Сонорные согласные',d:'Звонкие непарные согласные, в которых голос сильнее шума: [л], [м], [н], [р], [й\'] (и их мягкие пары).',ex:'лампа, мир, нора, рама',cat:'Фонетика и орфоэпия',f:'сонорн[а-яё]*',at:'zv3',see:['zvonk', 'shum']},
 shum:{t:'Шумные согласные',d:'Все согласные, кроме сонорных: в них шум сильнее голоса или есть только шум.',ex:'[б], [п], [з], [с], [ш], [х]',cat:'Фонетика и орфоэпия',f:'шумн(?:ый|ые|ых|ого|ому|ым|ыми)',at:'sl2',see:['sonor', 'soglasn']},
 razdel:{t:'Разделительные ъ и ь',d:'Знаки, которые показывают, что следующая гласная буква е, ё, ю, я обозначает два звука: [й\'] и гласный.',ex:'подъезд, съёмка; семья, вьюга',cat:'Фонетика и орфоэпия',f:'разделительн(?:ый|ого|ому|ым|ом|ые|ых)',at:'zv4',see:['bukva', 'myagk']},
 pozic:{t:'Сильная и слабая позиция',d:'Сильная позиция — та, где звук слышен ясно и не меняется (гласный под ударением, согласный перед гласным). В слабой позиции звук изменяется, и написание надо проверять.',ex:'во́ды — сильная позиция, вода́ — слабая; дубы — сильная, дуб [ду́п] — слабая',cat:'Фонетика и орфоэпия',f:'(?:сильн|слаб)(?:ая|ой|ую) позици[а-яё]*',at:'zv5',see:['oglush', 'bezud', 'orfogramma']},
 oglush:{t:'Оглушение',d:'Замена звонкого согласного парным глухим в конце слова и перед глухим согласным.',ex:'дуб [ду́п], ложка [ло́шка]',cat:'Фонетика и орфоэпия',f:'оглушени[а-яё]*|оглуша[а-яё]*',at:'zv5',see:['ozvonch', 'pozic', 'gluh']},
 ozvonch:{t:'Озвончение',d:'Замена глухого согласного парным звонким перед звонким шумным согласным.',ex:'просьба [про́з\'ба], сделать [зд\'е́лат\']',cat:'Фонетика и орфоэпия',f:'озвончени[а-яё]*|озвонча[а-яё]*',at:'zv5',see:['oglush', 'pozic', 'zvonk']},
 neproizn:{t:'Непроизносимый согласный',d:'Согласная буква, которая пишется, но звуком не произносится.',ex:'солнце [со́нцэ], чувство [ч\'у́ствъ]',cat:'Фонетика и орфоэпия',f:'непроизносим[а-яё]*',at:'zv5',see:['bukva', 'zvuk']},
 fon_razb:{t:'Фонетический разбор',d:'Разбор слова по звукам: слоги и ударение, характеристика каждого звука, число букв и звуков, транскрипция.',ex:'ель [й\'э́л\'] — 1 слог; 3 буквы, 3 звука',cat:'Фонетика и орфоэпия',f:'фонетическ(?:ий|ого|ому|им|ом) разбор[а-яё]*',at:'zv6',see:['transkr', 'zvuk', 'slog']},
 slog:{t:'Слог',d:'Звук или несколько звуков, которые произносятся одним толчком воздуха. Сколько в слове гласных, столько и слогов.',ex:'ма-ли-на — три слога',cat:'Фонетика и орфоэпия',f:'слог(?:а|у|ом|е|и|ов|ам|ами|ах)?',at:'sl1',see:['sloobr', 'otkr', 'perenos']},
 sloobr:{t:'Слогообразующий звук',d:'Звук, который образует слог. В русском языке это гласный.',ex:'в слове окно два слогообразующих звука: [а], [о]',cat:'Фонетика и орфоэпия',f:'слогообразующ[а-яё]*',at:'sl1',see:['slog', 'glasn']},
 otkr:{t:'Открытый и закрытый слог',d:'Открытый слог кончается гласным звуком, закрытый — согласным.',ex:'ма-ма — оба открытые; дом — закрытый; чай-ка — первый закрытый',cat:'Фонетика и орфоэпия',f:'(?:открыт|закрыт)(?:ый|ые|ых|ого|ому|ым|ыми|ом) слог[а-яё]*',at:'sl2',see:['slog']},
 perenos:{t:'Перенос',d:'Перенесение части слова с одной строки на другую по правилам: по слогам, не оставляя и не перенося одну букву, не отрывая й, ь, ъ от предыдущей буквы.',ex:'ко-ро-ва, чай-ка, кас-са, конь-ки',cat:'Фонетика и орфоэпия',f:'перенос(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'sl3',see:['slog', 'dvoin', 'stech']},
 dvoin:{t:'Двойные согласные',d:'Две одинаковые согласные буквы подряд. При переносе их разделяют.',ex:'кас-са, ван-на',cat:'Фонетика и орфоэпия',f:'двойн(?:ые|ых|ым|ыми) согласн[а-яё]*',at:'sl4',see:['perenos', 'stech']},
 stech:{t:'Стечение согласных',d:'Две или больше разные согласные подряд. При переносе их можно разделить по-разному; если среди них есть ь — только сразу после него.',ex:'се-стра, сес-тра, сест-ра; паль-то',cat:'Фонетика и орфоэпия',f:'стечени[а-яё]* согласн[а-яё]*',at:'sl4',see:['perenos', 'dvoin']},
 raznomest:{t:'Разноместное ударение',d:'Ударение, которое в разных словах может падать на любой слог: в русском языке нет постоянного места ударения.',ex:'ма́ма, кино́, молоко́, во́рон',cat:'Фонетика и орфоэпия',f:'разноместн[а-яё]*',at:'ud2',see:['udar', 'podvizh']},
 podvizh:{t:'Подвижное и неподвижное ударение',d:'Подвижное ударение переходит с одного слога на другой в формах одного слова, неподвижное остаётся на месте.',ex:'подвижное: голова́ — го́лову; неподвижное: кни́га — кни́ги',cat:'Фонетика и орфоэпия',f:'(?:не)?подвижн(?:ое|ого|ому|ым|ом) ударени[а-яё]*',at:'ud2',see:['udar', 'raznomest']},
 omograf:{t:'Омографы',d:'Слова, которые пишутся одинаково, а различаются ударением и значением.',ex:'за́мок — замо́к, му́ка — мука́',cat:'Фонетика и орфоэпия',f:'омограф[а-яё]*',at:'ud3',see:['udar']},
 // лексика: омонимы, синонимы, антонимы, паронимы (глава «Омонимы, синонимы, антонимы»)
 omonim:{t:'Омонимы',d:'Разные слова, которые одинаково звучат и пишутся, но не связаны по значению. В словаре — отдельные статьи с цифрами.',ex:'лук (растение) — лук (оружие); ключ (от замка) — ключ (родник)',cat:'Лексика',f:'омоним[а-яё]*',at:'om1',see:['omofon','omograf','omoforma','kalambur']},
 omofon:{t:'Омофоны',d:'Слова, которые звучат одинаково, а пишутся по-разному.',ex:'луг — лук, плод — плот, бал — балл',cat:'Лексика',f:'омофон[а-яё]*',at:'om1',see:['omonim','omograf','oglush']},
 omoforma:{t:'Омоформы',d:'Разные слова, которые совпадают только в одной форме и отвечают на разные вопросы.',ex:'печь (что?) — печь (что делать?); мой (чей?) — мой (что делай?)',cat:'Лексика',f:'омоформ[а-яё]*',at:'om1',see:['omonim']},
 kalambur:{t:'Каламбур',d:'Игра слов: шутка, построенная на омонимах, значениях многозначного слова или похожих по звучанию словах.',ex:'«Область рифм — моя стихия, / И легко пишу стихи я» (Д. Д. Минаев)',cat:'Лексика',f:'каламбур[а-яё]*',at:'om1',see:['omonim','paronim']},
 sin_ryad:{t:'Синонимический ряд',d:'Группа синонимов; первым стоит главное слово (доминанта) — самое общее и нейтральное.',ex:'идти, шагать, брести, плестись',cat:'Лексика',f:'синонимическ(?:ий|ого|ому|им|ом|ие|их) ряд[а-яё]*',at:'om2',see:['sinonim','dominanta']},
 sinonim:{t:'Синонимы',d:'Слова, близкие или одинаковые по значению, но разные по звучанию; отвечают на один и тот же вопрос. Различаются оттенком значения, окраской, сочетаемостью.',ex:'смелый — храбрый — отважный; смотреть — глядеть',cat:'Лексика',f:'синоним[а-яё]*',at:'om2',see:['sin_ryad','dominanta','antonim','paronim']},
 dominanta:{t:'Доминанта',d:'Главное слово синонимического ряда: называет общее значение ряда, нейтрально и уместно в любой речи.',ex:'в ряду «упасть, свалиться, шлёпнуться» доминанта — упасть',cat:'Лексика',f:'доминант[а-яё]*',at:'om2',see:['sin_ryad','sinonim']},
 antonim:{t:'Антонимы',d:'Слова с противоположным значением, отвечающие на один вопрос. Бывают однокоренные и разнокоренные; у многозначного слова к каждому значению свой антоним.',ex:'день — ночь, вход — выход, старый дом — новый, старый человек — молодой',cat:'Лексика',f:'антоним[а-яё]*',at:'om3',see:['antiteza','sinonim','oksimoron']},
 antiteza:{t:'Антитеза',d:'Резкое противопоставление в речи, обычно с помощью антонимов.',ex:'«Волна и камень, / Стихи и проза, лёд и пламень» (А. С. Пушкин)',cat:'Лексика',f:'антитез[а-яё]*',at:'om3',see:['antonim','oksimoron']},
 oksimoron:{t:'Оксюморон',d:'Соединение слов с противоположным смыслом в одном сочетании.',ex:'горькая радость, звонкая тишина, «Мёртвые души» (название поэмы Н. В. Гоголя)',cat:'Лексика',f:'оксюморон[а-яё]*',at:'om3',see:['antonim','antiteza']},
 paronim:{t:'Паронимы',d:'Однокоренные слова, похожие по звучанию, но разные по значению и сочетаемости. Смешение паронимов — речевая ошибка.',ex:'надеть (что?) — одеть (кого?); сытый — сытный; абонент — абонемент',cat:'Лексика',f:'пароним[а-яё]*',at:'om4',see:['sinonim','omofon','pleonazm']},
 pleonazm:{t:'Плеоназм',d:'Речевая ошибка: лишнее слово, которое повторяет смысл соседнего.',ex:'памятный сувенир, свободная вакансия, моя автобиография',cat:'Лексика',f:'плеоназм[а-яё]*',at:'lk5',see:['tavtol','paronim']},
 tavtol:{t:'Тавтология',d:'Повтор однокоренных слов рядом, обычно речевая ошибка.',ex:'рассказать рассказ, спросить вопрос (правильно: задать вопрос)',cat:'Лексика',f:'тавтологи[а-яё]*',at:'lk5',see:['pleonazm','sinonim']},
 orfoepia:{t:'Орфоэпия',d:'Раздел науки о языке о правильном литературном произношении и ударении.',ex:'звони́т, догово́р, кварта́л',cat:'Фонетика и орфоэпия',f:'орфоэпи(?:я|и|ю|ей)',at:'ud4',see:['orfoep_norma', 'orfoep_sl', 'norma']},
 orfoep_norma:{t:'Орфоэпическая норма',d:'Принятые в литературном языке правила произношения и ударения.',ex:'торт — то́рты (не торты́)',cat:'Фонетика и орфоэпия',f:'орфоэпическ(?:ая|ой|ую|ие|их) норм[а-яё]*',at:'ud4',see:['orfoepia', 'norma']},
 orfoep_sl:{t:'Орфоэпический словарь',d:'Словарь, в котором указаны правильное ударение и произношение слов.',ex:'в нём проверяют: кра́ны, баловА́ть',cat:'Фонетика и орфоэпия',f:'орфоэпическ(?:ий|ого|ому|им|ом) словар[а-яё]*',at:'ud4',see:['orfoepia']},
 bezud:{t:'Безударный гласный',d:'Гласный звук в слоге без ударения. Он слышится нечётко, поэтому его написание проверяют правилом или проверочным словом.',ex:'вода — проверка: во́ды; безударное окончание глагола: колеблют (I спряжение)',cat:'Орфография',f:'безударн[а-яё]*',at:'',see:['udar','glasn','okonch']},
 bud:{t:'Будущее время',d:'Время действия, которое произойдёт после момента речи. Причастий будущего времени в русском языке нет.',ex:'прочитает, будет читать; ошибка: «прочитающий», «сделающий»',cat:'Морфология',f:'будущ[а-яё]* врем(?:я|ени|енем)',at:'pr2',see:['nast','prosh','vremya']},
 bukva:{t:'Буква',d:'Знак, которым звук обозначается на письме. Звуки мы слышим и произносим, а буквы видим и пишем; их число в слове может не совпадать.',ex:'юный — 4 буквы, 5 звуков',cat:'Общие понятия',f:'букв(?:а|ы|е|у|ой|ам|ами|ах)?',at:'',see:['zvuk','glasn','orfogr']},
 vid:{t:'Вид глагола',d:'Признак глагола, который показывает, доведено ли действие до конца. Вид бывает совершенный и несовершенный.',ex:'читать (что делать?) — прочитать (что сделать?)',cat:'Морфология',f:'вид(?:а|у|ом|е)? глагол[а-яё]*',at:'pr2',see:['sov','nesov','glag']},
 vozvr:{t:'Возвратность',d:'Признак глагола и причастия, выраженный постфиксом -ся (-сь). В причастиях -ся не сокращается до -сь даже после гласной.',ex:'строящийся, умывшийся, строящаяся',cat:'Морфология',f:'возвратн[а-яё]*',at:'pr1',see:['postf','neperekh']},
 vremya:{t:'Время глагола',d:'Признак глагола, который показывает, когда совершается действие по отношению к моменту речи. У причастий есть только настоящее и прошедшее время.',ex:'читающий (настоящее), читавший (прошедшее)',cat:'Морфология',f:'врем(?:я|ени) глагол[а-яё]*',at:'pr2',see:['nast','prosh','bud']},
 glavslovo:{t:'Главное слово',d:'Слово в словосочетании, от которого задают вопрос к зависимому слову.',ex:'читающий (что?) книгу: «читающий» — главное слово, «книгу» — зависимое',cat:'Синтаксис и пунктуация',f:'главн(?:ое|ого|ому|ым) слов(?:о|а|у|ом)',at:'',see:['dep','slovosoch']},
 glag:{t:'Глагол',d:'Самостоятельная часть речи, которая обозначает действие или состояние и отвечает на вопросы «что делать? что сделать?».',ex:'читать, прочитать, строить, спать',cat:'Морфология',f:'глагол(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'',see:['vid','vremya','sprya','prich']},
 gl_iskl:{t:'Глаголы-исключения',d:'Глаголы, которые нарушают общее правило определения спряжения: гнать, держать, дышать, слышать, смотреть, видеть, ненавидеть, обидеть, терпеть, вертеть, зависеть относятся ко II спряжению, а брить, стелить — к I, хотя оканчиваются на -ить.',ex:'гонят → гонящий, гонимый; видят → видимый',cat:'Морфология',f:'глагол[а-яё]*-исключени[а-яё]*',at:'pr4',see:['sprya','iskl','infin']},
 glasn:{t:'Гласный звук',d:'Звук, который произносится голосом, свободно, без преград во рту. Гласных букв в русском языке десять: а, о, у, ы, э, я, ё, ю, е, и.',ex:'обидеть → обидевший: перед -вш- та же гласная, что перед -ть',cat:'Общие понятия',f:'гласн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'',see:['soglasn','bezud','udar']},
 gram_priznak:{t:'Грамматический признак',d:'Свойство слова, которое выражается его формой: род, число, падеж, вид, время, залог и другие. Признаки бывают постоянными и непостоянными.',ex:'прочитанная: страдательное, прошедшего времени, совершенного вида, ж. р., ед. ч., И. п.',cat:'Морфология',f:'признак(?:и|ов|ам|ами|ах) (?:глагол|прилагательн)[а-яё]*',at:'pr1',see:['chast_rechi','morf_razb','forma']},
 deepr:{t:'Деепричастие',d:'Особая неизменяемая форма глагола, которая обозначает добавочное действие и отвечает на вопросы «что делая? что сделав?».',ex:'читая, прочитав, улыбаясь',cat:'Морфология',f:'деепричасти[а-яё]*',at:'',see:['prich','glag','obst']},
 dejst:{t:'Действительное причастие',d:'Причастие, которое называет признак предмета, совершающего действие сам.',ex:'читающий ученик (ученик читает), распустившийся цветок',cat:'Морфология',f:'действительн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'pr2',see:['strad','zalog','prich']},
 defis:{t:'Дефис',d:'Короткая чёрточка внутри слова или между частями сочетания. Через дефис пишутся, например, повторы.',ex:'глаженые-переглаженые, стираное-перестираное',cat:'Орфография',f:'дефис[а-яё]*',at:'',see:['povtor','slitno','razdelno']},
 dobav:{t:'Добавочное значение',d:'Дополнительный оттенок смысла у причастного оборота: причина («так как») или уступка («хотя»). С таким значением оборот перед определяемым словом тоже может обособляться.',ex:'Утомлённые долгой дорогой, путники быстро уснули (= так как были утомлены).',cat:'Синтаксис и пунктуация',f:'добавочн[а-яё]* значени[а-яё]*',at:'pr7',see:['obosob','prich_ob']},
 dop:{t:'Дополнение',d:'Второстепенный член предложения, который обозначает предмет и отвечает на вопросы косвенных падежей: «кого? чего? кому? чем? о чём?».',ex:'решена (кем?) учеником; уверены (в чём?) в победе',cat:'Синтаксис и пунктуация',f:'дополнени[а-яё]*',at:'',see:['chlen','upravl','padezh']},
 dep:{t:'Зависимое слово',d:'Слово, которое подчиняется другому слову и отвечает на вопрос, заданный от него. Если у причастия есть зависимое слово, пишется нн, а не — раздельно.',ex:'жаренная (на чём?) на масле картошка; не прочитанная (кем?) мною книга',cat:'Синтаксис и пунктуация',f:'зависим(?:ое|ого|ому|ым|ом|ые|ых|ыми) слов[а-яё]*|слов[а-яё]*-помощник[а-яё]*',at:'nn2',see:['glavslovo','slovosoch','prich_ob']},
 zalog:{t:'Залог',d:'Признак глагола и причастия, который показывает, сам ли предмет совершает действие или действие направлено на него. Причастия бывают действительного и страдательного залога.',ex:'читающий ученик — читаемая книга',cat:'Морфология',f:'залог(?:а|у|ом|е|и|ов)?',at:'pr2',see:['dejst','strad','prich']},
 zapyat:{t:'Запятая',d:'Знак препинания, который разделяет или выделяет части предложения. Причастный оборот после определяемого слова выделяется запятыми с двух сторон.',ex:'Листья, опавшие за ночь, лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'запят(?:ая|ой|ую|ые|ых|ыми|ым)',at:'pr7',see:['znaki','obosob']},
 zvuk:{t:'Звук',d:'Самая маленькая единица звучащей речи. Звуки бывают гласные и согласные.',ex:'гласные [а], [о]; согласные [н], [ш]',cat:'Общие понятия',f:'звук(?:а|у|ом|е|и|ов|ам|ами|ах)?',at:'zv1',see:['bukva','glasn','soglasn']},
 znaki:{t:'Знаки препинания',d:'Знаки, которые делят письменную речь на предложения и их части: точка, запятая, тире, двоеточие и другие.',ex:'. , — : ; ! ?',cat:'Синтаксис и пунктуация',f:'знак[а-яё]* препинани[а-яё]*',at:'',see:['zapyat','punkt']},
 infin:{t:'Инфинитив',d:'Начальная (неопределённая) форма глагола. Отвечает на вопросы «что делать? что сделать?» и оканчивается на -ть, -ти, -чь.',ex:'читать, нести, беречь',cat:'Морфология',f:'инфинитив[а-яё]*|неопредел[её]нн[а-яё]* форм[а-яё]*',at:'pr3',see:['osn_inf','glag','sprya']},
 iskl:{t:'Исключение',d:'Слово, которое пишется не по общему правилу. Исключения запоминают списком.',ex:'стеклянный, оловянный, деревянный; ветреный; движимый',cat:'Орфография',f:'исключени[а-яё]*',at:'nn1',see:['orfogr','gl_iskl']},
 koren:{t:'Корень',d:'Главная часть слова, в которой заключено общее значение всех однокоренных слов.',ex:'кож-а, кож-аный, кож-ица; ков-ать, ков-аный',cat:'Морфемика и словообразование',f:'корень|корн(?:я|ю|ем|е|и|ей|ям|ями|ях)',at:'',see:['odnokor','morfema','suff']},
 krat:{t:'Краткая форма',d:'Укороченная форма прилагательного или страдательного причастия. Не изменяется по падежам и обычно бывает сказуемым.',ex:'длинный → длинен, длинна; прочитанный → прочитан, прочитана',cat:'Морфология',f:'кратк[а-яё]* форм[а-яё]*',at:'pr5',see:['poln','krprich','krpril']},
 krpril:{t:'Краткое прилагательное',d:'Краткая форма прилагательного. Называет качество, отвечает на вопрос «каков?», к нему подходит слово «очень». Пишется с тем же числом н, что и полная форма.',ex:'девушка воспитанна (воспитанная), дорога длинна',cat:'Морфология',f:'кратк[а-яё]* прилагательн[а-яё]*',at:'nn4',see:['krat','krprich','pril']},
 krprich:{t:'Краткое причастие',d:'Краткая форма страдательного причастия. Изменяется по родам и числам, в предложении — сказуемое, пишется с одной н.',ex:'книга прочитана, задача решена (кем?) учеником',cat:'Морфология',f:'кратк[а-яё]* причасти[а-яё]*',at:'pr5',see:['krat','strad','skaz']},
 znach:{t:'Лексическое значение',d:'Смысл слова — то, что оно обозначает: предмет, признак, действие, явление. От значения иногда зависит написание.',ex:'сугроб — куча снега, наметённая ветром; масляный (из масла) — масленый (смазанный маслом)',cat:'Лексика',f:'лексическ[а-яё]* значени[а-яё]*',at:'lk1',see:['tolk_sl','mnogozn','ustoich']},
 lityaz:{t:'Литературный язык',d:'Образцовая форма языка с едиными для всех нормами. На нём пишут книги и газеты, говорят на уроках и в официальной обстановке.',ex:'от «писать» страдательное причастие настоящего времени в литературном языке не употребляется',cat:'Общие понятия',f:'литературн[а-яё]* язык[а-яё]*',at:'',see:['norma','razgovor']},
 litso:{t:'Лицо',d:'Признак глагола и личного местоимения, который показывает, кто совершает действие: говорящий (1-е лицо), собеседник (2-е) или тот, о ком говорят (3-е).',ex:'я читаю, ты читаешь, они читают',cat:'Морфология',f:'[123]-(?:е|го|м) лиц(?:о|а|у|ом|е)',at:'pr3',see:['osn_nast','lichmest','chislo']},
 lichmest:{t:'Личное местоимение',d:'Местоимение, которое указывает на участника речи или на того, о ком говорят: я, ты, он, она, оно, мы, вы, они. Причастный оборот при личном местоимении выделяется запятыми всегда.',ex:'Мы, уставшие после похода, легли спать.',cat:'Морфология',f:'личн[а-яё]* местоимени[а-яё]*',at:'pr7',see:['mest','obosob','litso']},
 mest:{t:'Местоимение',d:'Самостоятельная часть речи, которая указывает на предмет, признак или количество, но не называет их.',ex:'я, мы, он, кто, какой, этот, мой',cat:'Морфология',f:'местоимени[а-яё]*',at:'',see:['lichmest','chast_rechi']},
 morfema:{t:'Морфема',d:'Самая маленькая значимая часть слова: приставка, корень, суффикс, окончание, постфикс.',ex:'за-жар-енн-ый',cat:'Морфемика и словообразование',f:'морфем(?:а|ы|е|у|ой|ам|ами|ах)?',at:'',see:['koren','pref','suff','okonch']},
 morfemika:{t:'Морфемика',d:'Раздел науки о языке, который изучает состав слова: корни, приставки, суффиксы, окончания.',ex:'разбор по составу: за-жар-енн-ый',cat:'Общие понятия',f:'морфемик(?:а|и|е|у|ой)',at:'',see:['morfema','morf_sostav','slovoobr']},
 morf_razb:{t:'Морфологический разбор',d:'Описание слова как части речи: его начальная форма, постоянные и непостоянные признаки и роль в предложении.',ex:'прочитанная — причастие, от глагола прочитать; страдательное, прошедшего времени…',cat:'Морфология',f:'морфологическ[а-яё]* разбор[а-яё]*',at:'',see:['gram_priznak','chast_rechi']},
 morfologia:{t:'Морфология',d:'Раздел науки о языке, который изучает части речи и формы слов.',ex:'причастие, его разряды и склонение',cat:'Общие понятия',f:'морфологи(?:я|и|ю|ей)',at:'',see:['chast_rechi','morf_razb','morfemika']},
 naklon:{t:'Наклонение',d:'Признак глагола, который показывает, как действие связано с действительностью: происходит на самом деле, желательно или требуется. Наклонения: изъявительное, условное, повелительное.',ex:'читает, читал бы, читай',cat:'Морфология',f:'наклонени[а-яё]*',at:'',see:['glag','vremya','litso']},
 narech:{t:'Наречие',d:'Неизменяемая самостоятельная часть речи, которая обозначает признак действия или другого признака и отвечает на вопросы «как? где? когда?».',ex:'неожиданно, взволнованно, ветрено',cat:'Морфология',f:'наречи(?:е|я|ю|ем|и|й|ям|ями|ях)',at:'nn5',see:['obst','pril','krprich']},
 nast:{t:'Настоящее время',d:'Время действия, которое происходит в момент речи. Причастия настоящего времени образуются от основы настоящего времени и только от глаголов несовершенного вида.',ex:'читающий, строящий, читаемый, видимый',cat:'Морфология',f:'настоящ[а-яё]* врем(?:я|ени|енем)',at:'pr2',see:['prosh','osn_nast','nesov']},
 ne_prich:{t:'Не с причастиями',d:'Правило написания не. Слитно — с полным причастием без зависимых слов; раздельно — при зависимых словах, при противопоставлении с «а» и с краткой формой.',ex:'непрочитанная книга — не прочитанная мною книга — книга не прочитана',cat:'Орфография',f:'не с причасти[а-яё]*',at:'pr6',see:['slitno','razdelno','chastica','dep']},
 neperekh:{t:'Непереходный глагол',d:'Глагол, при котором не может стоять дополнение в винительном падеже без предлога. Страдательных причастий от него нет.',ex:'спать, идти, кипеть, строиться',cat:'Морфология',f:'непереходн[а-яё]*',at:'pr2',see:['perekh','vozvr','strad']},
 nesov:{t:'Несовершенный вид',d:'Вид глагола, который называет действие без указания на его завершение и отвечает на вопрос «что делать?». Только от таких глаголов образуются причастия настоящего времени.',ex:'читать → читающий, читаемый',cat:'Морфология',f:'несовершенн[а-яё]* вид(?:а|у|ом|е)?',at:'pr2',see:['sov','vid','nast']},
 nul:{t:'Нулевое окончание',d:'Окончание, которое не выражено ни звуком, ни буквой, но показывает форму слова.',ex:'лимон, конь, (книга) прочитан',cat:'Морфемика и словообразование',f:'нулев[а-яё]* окончани[а-яё]*',at:'',see:['okonch','osnova']},
 obosob:{t:'Обособление',d:'Выделение части предложения запятыми на письме и интонацией в речи. Причастный оборот обособляется, если стоит после определяемого слова или относится к личному местоимению.',ex:'Листья, опавшие за ночь, лежали на дорожке. Уставшие после похода, мы легли спать.',cat:'Синтаксис и пунктуация',f:'обособ[а-яё]*|выделя(?:ется|ются|ться) запят[а-яё]*',at:'pr7',see:['prich_ob','zapyat','opr_slovo','dobav']},
 obst:{t:'Обстоятельство',d:'Второстепенный член предложения, который показывает, как, где, когда или почему совершается действие. Часто выражается наречием.',ex:'Он отвечал обдуманно. Листья лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'обстоятельств[а-яё]*',at:'',see:['narech','chlen','deepr']},
 odnokor:{t:'Однокоренные слова',d:'Слова с одним и тем же корнем и близким значением.',ex:'жарить, жареный, зажаренный, жаркое',cat:'Морфемика и словообразование',f:'однокоренн[а-яё]*',at:'',see:['koren','ishod']},
 okonch:{t:'Окончание',d:'Изменяемая часть слова, которая показывает его связь с другими словами. Окончание полного причастия проверяют вопросом от существительного.',ex:'о (каком?) читающем мальчике; с (какой?) прочитанной книгой',cat:'Морфемика и словообразование',f:'окончани[а-яё]*',at:'pr5',see:['osnova','nul','sklon']},
 opred:{t:'Определение',d:'Второстепенный член предложения, который обозначает признак предмета и отвечает на вопросы «какой? чей?». Полное причастие и причастный оборот в предложении — определение.',ex:'прочитанная книга; листья, опавшие за ночь',cat:'Синтаксис и пунктуация',f:'определени[а-яё]*',at:'pr1',see:['opr_slovo','prich_ob','chlen']},
 opr_slovo:{t:'Определяемое слово',d:'Слово, к которому относится определение или причастный оборот. С ним причастие согласуется, и от него задают вопрос «какой?».',ex:'Листья (какие?), опавшие за ночь, … — определяемое слово «листья»',cat:'Синтаксис и пунктуация',f:'определяем(?:ое|ого|ому|ым|ом|ые|ых|ыми)',at:'pr7',see:['opred','prich_ob','obosob']},
 orfogramma:{t:'Орфограмма',d:'Место в слове, где можно ошибиться и где написание выбирают по правилу.',ex:'н или нн в «жаре_ый»; гласная в «колебл_щий»',cat:'Орфография',f:'орфограмм[а-яё]*',at:'',see:['orfogr','pravop']},
 orfogr:{t:'Орфография',d:'Система правил написания слов и раздел науки о языке, который эти правила изучает.',ex:'правописание н и нн, не с причастиями, гласных в суффиксах',cat:'Орфография',f:'орфографи[а-яё]*',at:'',see:['orfogramma','pravop','punkt']},
 osnova:{t:'Основа',d:'Часть слова без окончания и постфикса. Если основа оканчивается на н, а суффикс тоже начинается с н, получается нн.',ex:'лимон + н → лимонный; чита-ть: основа инфинитива чита-',cat:'Морфемика и словообразование',f:'основ(?:а|ы|е|у|ой|ам|ами|ах)?',at:'pr3',see:['osn_nast','osn_inf','okonch','styk']},
 osn_inf:{t:'Основа инфинитива',d:'Часть инфинитива без -ть (-ти). От неё образуются причастия прошедшего времени.',ex:'чита-ть → чита-вший, чита-нный; увиде-ть → увиде-вший',cat:'Морфемика и словообразование',f:'основ[а-яё]* инфинитива',at:'pr3',see:['osn_nast','prosh','infin']},
 osn_nast:{t:'Основа настоящего времени',d:'Основа глагола, которую легко найти, отбросив окончание в форме «они …». От неё образуются причастия настоящего времени.',ex:'они чита-ют → чита-ющий; они нес-ут → нес-омый',cat:'Морфемика и словообразование',f:'основ[а-яё]* настоящего времени',at:'pr3',see:['osn_inf','nast','sprya']},
 otgl:{t:'Отглагольное прилагательное',d:'Прилагательное, образованное от глагола. В отличие от причастия, оно называет постоянный признак без действия и пишется с одной н.',ex:'жареная рыба (но: зажаренная на огне — причастие); варёный, кованый',cat:'Морфология',f:'отглагольн[а-яё]*',at:'nn2',see:['prich','otym','glag']},
 otym:{t:'Отымённое прилагательное',d:'Прилагательное, образованное от существительного. Сколько в нём писать н, зависит от суффикса.',ex:'кожа → кожаный, клюква → клюквенный, лимон → лимонный',cat:'Морфология',f:'отым[её]нн[а-яё]*',at:'nn1',see:['pril','suff','otgl','sush']},
 padezh:{t:'Падеж',d:'Форма имени, которая показывает его связь с другими словами в предложении. Падежей шесть: именительный, родительный, дательный, винительный, творительный, предложный.',ex:'читающего ученика (Р. п.), читающими детьми (Т. п.)',cat:'Морфология',f:'падеж(?:а|у|ом|е|и|ей|ам|ами|ах)?',at:'',see:['sklon','rod','chislo']},
 perekhod:{t:'Переход в другую часть речи',d:'Случай, когда слово теряет прежние признаки и начинает употребляться как слово другой части речи.',ex:'блестящий ответ (прилагательное); учащиеся, заведующий (существительные)',cat:'Морфология',f:'переход(?:а|ом|е)? в (?:прилагательн|существительн)[а-яё]*',at:'pr1',see:['prich','pril','sush']},
 perekh:{t:'Переходный глагол',d:'Глагол, который может управлять существительным в винительном падеже без предлога. Только от переходных глаголов образуются страдательные причастия.',ex:'читать (что?) книгу → читаемая книга',cat:'Морфология',f:'переходн[а-яё]*',at:'pr2',see:['neperekh','strad','upravl']},
 povtor:{t:'Повтор',d:'Сочетание из одного слова, взятого дважды, во второй раз — с приставкой пере-. Обозначает высокую степень качества; обе части пишутся с одной н.',ex:'глаженые-переглаженые брюки, штопаные-перештопаные носки',cat:'Морфемика и словообразование',f:'повтор(?:ы|ах|ов|ами)?',at:'nn3',see:['defis','otgl','pref']},
 podl:{t:'Подлежащее',d:'Главный член предложения, который называет, о ком или о чём говорится. Отвечает на вопросы «кто?» или «что?».',ex:'Задача решена. Мы легли спать.',cat:'Синтаксис и пунктуация',f:'подлежащ(?:ее|его|ему|им|ем|ие|их|ими)',at:'',see:['skaz','chlen','predl']},
 poln:{t:'Полная форма',d:'Основная форма прилагательного или причастия, которая изменяется по родам, числам и падежам и в предложении обычно бывает определением.',ex:'прочитанная книга, длинная дорога',cat:'Морфология',f:'полн[а-яё]* форм[а-яё]*|полн[а-яё]* и кратк[а-яё]* форм[а-яё]*',at:'pr5',see:['krat','opred','sklon']},
 postf:{t:'Постфикс',d:'Часть слова, которая стоит после окончания. В глаголах и причастиях это -ся (-сь); он делает слово возвратным.',ex:'строящий-ся, умывший-ся',cat:'Морфемика и словообразование',f:'постфикс[а-яё]*',at:'pr1',see:['vozvr','suff','okonch']},
 pravop:{t:'Правописание',d:'Написание слов по правилам орфографии; так называют и само правило.',ex:'правописание причастий, правописание н и нн',cat:'Орфография',f:'правописани[а-яё]*',at:'pr6',see:['orfogr','orfogramma']},
 predlog:{t:'Предлог',d:'Служебная часть речи, которая связывает существительное или местоимение с другими словами.',ex:'жаренная на масле; о читающем мальчике; с книгой',cat:'Морфология',f:'предлог(?:а|у|ом|е|и|ов|ами|ах)?',at:'',see:['sluzh','padezh','soyuz']},
 predl:{t:'Предложение',d:'Слово или несколько слов, которые выражают законченную мысль. В конце предложения ставится точка, вопросительный или восклицательный знак.',ex:'Книга прочитана. Листья лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'предложени[а-яё]*',at:'',see:['chlen','podl','skaz']},
 priznak:{t:'Признак предмета',d:'Свойство предмета: цвет, качество, материал, принадлежность. Прилагательное называет постоянный признак, причастие — признак по действию.',ex:'синий (просто цвет) — синеющий (который синеет)',cat:'Морфология',f:'признак[а-яё]* предмет[а-яё]*',at:'pr1',see:['pril','prich','opred']},
 pril:{t:'Прилагательное',d:'Самостоятельная часть речи, которая обозначает признак предмета и отвечает на вопросы «какой? чей?». Изменяется по родам, числам и падежам.',ex:'кожаный, лимонный, длинный, красивый',cat:'Морфология',f:'прилагательн[а-яё]*',at:'',see:['otym','otgl','prich','krpril']},
 pref:{t:'Приставка',d:'Значимая часть слова перед корнем, которая служит для образования новых слов: при-бежать, пере-писать. Пишется слитно со словом, в отличие от предлога. В отглагольных словах приставка (кроме не-) указывает на причастие и две н.',ex:'под-ъезд, рас-сказ, пре-красный, при-морский; в «Н и НН»: за-жаренный, но не-крашеный',cat:'Морфемика и словообразование',f:'приставк[а-яё]*|приставочн[а-яё]*',at:'ps1',see:['koren','suff','otgl']},
 prich:{t:'Причастие',d:'Особая форма глагола, которая обозначает признак предмета по действию и отвечает на вопросы «какой? что делающий? что сделавший?». Сочетает признаки глагола и прилагательного.',ex:'бегущий ручей (который бежит), прочитанная книга (которую прочитали)',cat:'Морфология',f:'причасти[а-яё]*',at:'pr1',see:['deepr','pril','glag','prich_ob']},
 prich_ob:{t:'Причастный оборот',d:'Причастие вместе с зависимыми словами. В предложении весь оборот — одно определение.',ex:'дети, игравшие во дворе; опавшие за ночь листья',cat:'Синтаксис и пунктуация',f:'причастн[а-яё]* оборот[а-яё]*',at:'pr7',see:['prich','dep','obosob','opr_slovo']},
 proizv:{t:'Производное слово',d:'Слово, образованное от другого слова с помощью приставки, суффикса или иным способом.',ex:'кожаный (от «кожа»), воспитанник (от «воспитанный»)',cat:'Морфемика и словообразование',f:'производн[а-яё]* слов[а-яё]*',at:'',see:['ishod','slovoobr']},
 ishod:{t:'Производящее слово',d:'Слово, от которого образовано другое слово; его называют также исходным. С него начинается проверка н и нн.',ex:'кожа → кожаный; неожиданный → неожиданно; гостиный → гостиная',cat:'Морфемика и словообразование',f:'исходн[а-яё]* слов[а-яё]*|производящ[а-яё]* слов[а-яё]*',at:'nn1',see:['proizv','slovoobr','odnokor']},
 protivop:{t:'Противопоставление',d:'Сочетание, в котором одно отрицается, а другое утверждается, обычно с союзом «а». При противопоставлении не с причастием пишется раздельно.',ex:'не прочитанная, а пролистанная книга',cat:'Синтаксис и пунктуация',f:'противопоставлени[а-яё]*',at:'pr6',see:['ne_prich','soyuz','razdelno']},
 prosh:{t:'Прошедшее время',d:'Время действия, которое было до момента речи. Причастия прошедшего времени образуются от основы инфинитива.',ex:'читавший, нёсший, прочитанный, взятый',cat:'Морфология',f:'прошедш[а-яё]* врем(?:я|ени|енем)',at:'pr2',see:['nast','osn_inf','bud']},
 punkt:{t:'Пунктуация',d:'Правила расстановки знаков препинания, а также раздел науки о языке, который их изучает.',ex:'запятые при причастном обороте',cat:'Синтаксис и пунктуация',f:'пунктуаци[а-яё]*',at:'',see:['znaki','zapyat','sintaksis']},
 morf_sostav:{t:'Разбор по составу',d:'Выделение в слове всех его частей: приставки, корня, суффикса, окончания, постфикса.',ex:'за-жар-енн-ый, вы-мыт-ый, строя-щ-ий-ся',cat:'Морфемика и словообразование',f:'разбор[а-яё]* (?:слова )?по составу|морфемн[а-яё]* разбор[а-яё]*',at:'',see:['morfema','koren','suff']},
 razgovor:{t:'Разговорная форма',d:'Форма слова, привычная в непринуждённой устной речи, но не соответствующая строгой литературной норме.',ex:'мерять, мучать (литературные: мерить, мучить)',cat:'Общие понятия',f:'разговорн[а-яё]*',at:'',see:['norma','lityaz']},
 razdelno:{t:'Раздельное написание',d:'Написание слов отдельно друг от друга, через пробел.',ex:'не прочитанная мною книга; книга не прочитана',cat:'Орфография',f:'раздельн(?:о|ое|ого|ому|ым|ом)',at:'pr6',see:['slitno','defis','ne_prich']},
 razryad:{t:'Разряд',d:'Группа слов одной части речи, объединённых общим признаком. Причастия делятся на четыре разряда по залогу и времени.',ex:'действительные настоящего времени: читающий; страдательные прошедшего: прочитанный',cat:'Морфология',f:'разряд(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'pr2',see:['zalog','vremya','dejst','strad']},
 rod:{t:'Род',d:'Признак, по которому слова делятся на мужской, женский и средний род. У существительного род постоянный, а прилагательное и причастие меняют род вслед за существительным.',ex:'читающий мальчик, читающая девочка, читающее дитя',cat:'Морфология',f:'(?:мужск|женск|средн)[а-яё]* род(?:а|у|ом|е)?',at:'',see:['chislo','padezh','soglas']},
 samost:{t:'Самостоятельная часть речи',d:'Часть речи, слова которой называют предметы, признаки, действия или количество и бывают членами предложения.',ex:'существительное, прилагательное, глагол, наречие',cat:'Морфология',f:'самостоятельн[а-яё]* част[а-яё]* речи',at:'pr1',see:['chast_rechi','sluzh']},
 sintaksis:{t:'Синтаксис',d:'Раздел науки о языке, который изучает словосочетания и предложения.',ex:'причастный оборот и запятые при нём',cat:'Общие понятия',f:'синтаксис[а-яё]*',at:'',see:['predl','slovosoch','punkt']},
 skaz:{t:'Сказуемое',d:'Главный член предложения, который сообщает, что делает подлежащее, каково оно или что с ним происходит. Краткое причастие в предложении — сказуемое.',ex:'Задача решена. Дорога длинна. Ученики собрались.',cat:'Синтаксис и пунктуация',f:'сказуем[а-яё]*',at:'pr5',see:['podl','krprich','chlen']},
 sklon:{t:'Склонение',d:'Изменение слова по падежам и числам. Полное причастие склоняется так же, как прилагательное.',ex:'читающий, читающего, читающему, о читающем',cat:'Морфология',f:'склонени[а-яё]*|склоня(?:ется|ются)',at:'pr5',see:['padezh','okonch','poln']},
 slitno:{t:'Слитное написание',d:'Написание частей слова вместе, без пробела и дефиса.',ex:'непрочитанная книга, незваный, ненавидящий',cat:'Орфография',f:'слитн(?:о|ое|ого|ому|ым|ом)',at:'pr6',see:['razdelno','defis','ne_prich']},
 slovoobr:{t:'Словообразование',d:'Образование новых слов от уже существующих, а также раздел науки о языке, который это изучает.',ex:'дружина → дружинник; жарить → жареный',cat:'Морфемика и словообразование',f:'словообразовани[а-яё]*|словообразовательн[а-яё]*',at:'',see:['ishod','proizv','morfema']},
 slovosoch:{t:'Словосочетание',d:'Два или больше самостоятельных слова, связанных по смыслу и грамматически: одно из них главное, другое зависимое.',ex:'читаемая книга, мощённая булыжником, любующийся закатом',cat:'Синтаксис и пунктуация',f:'словосочетани[а-яё]*',at:'',see:['glavslovo','dep','soglas','upravl']},
 slozhn:{t:'Сложное слово',d:'Слово, в котором два корня или больше.',ex:'гладкокрашеный, домотканый, свежемороженый',cat:'Морфемика и словообразование',f:'сложн(?:ое|ого|ому|ым|ом|ые|ых|ыми) слов[а-яё]*',at:'nn3',see:['koren','slozhnosokr']},
 slozhnosokr:{t:'Сложносокращённое слово',d:'Слово, составленное из сокращённых частей нескольких слов.',ex:'юннат (юный натуралист), вуз, спецкор',cat:'Морфемика и словообразование',f:'сложносокращ[её]нн[а-яё]*',at:'nn1',see:['slozhn','styk']},
 sluzh:{t:'Служебная часть речи',d:'Часть речи, слова которой ничего не называют и не бывают членами предложения: они связывают слова или добавляют оттенки смысла.',ex:'предлоги, союзы, частицы',cat:'Морфология',f:'служебн[а-яё]* част[а-яё]* речи',at:'',see:['chast_rechi','predlog','soyuz','chastica']},
 sov:{t:'Совершенный вид',d:'Вид глагола, который обозначает законченное действие или его результат и отвечает на вопрос «что сделать?». Причастие от глагола совершенного вида пишется с нн даже без приставки.',ex:'бросить → брошенный, решить → решённый, купить → купленный',cat:'Морфология',f:'совершенн[а-яё]* вид(?:а|у|ом|е)?',at:'pr2',see:['nesov','vid','prich']},
 soglasn:{t:'Согласный звук',d:'Звук, при произнесении которого воздух встречает во рту преграду: губы, зубы или язык.',ex:'н, т, ш, ж; нёс-ший: после согласной суффикс -ш-',cat:'Общие понятия',f:'согласн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'',see:['glasn','shipyash','zvuk']},
 soglas:{t:'Согласование',d:'Связь, при которой зависимое слово ставится в том же роде, числе и падеже, что и главное. Так причастие и прилагательное связаны с существительным.',ex:'читающего ученика, читающей девочке, читающими детьми',cat:'Синтаксис и пунктуация',f:'согласовани[а-яё]*|согласу(?:ется|ются|ющ[а-яё]*)',at:'pr1',see:['upravl','rod','chislo','padezh']},
 soyuz:{t:'Союз',d:'Служебная часть речи, которая связывает однородные члены предложения или части сложного предложения.',ex:'и, а, но, потому что; не прочитанная, а пролистанная',cat:'Морфология',f:'союз(?:а|у|ом|е|ы|ов|ами|ах)?',at:'',see:['sluzh','protivop','chastica']},
 sprya:{t:'Спряжение',d:'Изменение глагола по лицам и числам; так же называют две группы глаголов — I и II спряжение — с разными личными окончаниями. От спряжения зависит гласная в суффиксе причастия настоящего времени.',ex:'I: колеблют → колеблющий; II: клеят → клеящий, видят → видимый',cat:'Морфология',f:'спряжени[а-яё]*',at:'pr4',see:['gl_iskl','osn_nast','litso','okonch']},
 strad:{t:'Страдательное причастие',d:'Причастие, которое называет признак предмета, на который направлено чужое действие. Образуется только от переходных глаголов.',ex:'читаемая учеником книга, построенный дом',cat:'Морфология',f:'страдательн[а-яё]*',at:'pr2',see:['dejst','zalog','perekh','krprich']},
 styk:{t:'Стык морфем',d:'Место, где встречаются две части слова. Если основа оканчивается на н, а суффикс начинается с н, на стыке пишется нн.',ex:'лимон + н → лимонный; дружина + ник → дружинник',cat:'Морфемика и словообразование',f:'стык(?:а|е|ом|и|ах)?',at:'nn1',see:['osnova','suff','morfema']},
 suff:{t:'Суффикс',d:'Часть слова после корня, которая служит для образования новых слов или форм. В прилагательных и причастиях от суффикса зависит, сколько писать н.',ex:'кож-ан-ый, клюкв-енн-ый, марин-ова-нный, чита-ющ-ий',cat:'Морфемика и словообразование',f:'суффикс[а-яё]*',at:'nn1',see:['pref','koren','suff_prich']},
 suff_prich:{t:'Суффиксы причастий',d:'Суффиксы, с помощью которых причастия образуются от глагола: -ущ-/-ющ-, -ащ-/-ящ-, -ем-/-ом-, -им-, -вш-, -ш-, -нн-, -енн-, -т-.',ex:'несущий, видимый, читавший, нёсший, прочитанный, взятый',cat:'Морфемика и словообразование',f:'суффикс[а-яё]* причасти[а-яё]*',at:'pr3',see:['suff','sprya','osn_nast','osn_inf']},
 sush:{t:'Существительное',d:'Самостоятельная часть речи, которая обозначает предмет и отвечает на вопросы «кто? что?». Имеет род, изменяется по числам и падежам.',ex:'кожа, лимон, дружинник, мороженое',cat:'Морфология',f:'существительн[а-яё]*',at:'nn6',see:['pril','rod','padezh']},
 udar:{t:'Ударение',d:'Выделение одного слога в слове голосом: ударный гласный звучит дольше и чётче остальных. Русское ударение разноместное и подвижное.',ex:'вода́ — во́ды; за́мок — замо́к; на выбор н или нн ударение не влияет: ржано́й, ко́жаный',cat:'Общие понятия',f:'ударени[а-яё]*|ударн(?:ый|ая|ое|ые|ого|ой|ом|ых|ым)',at:'ud1',see:['bezud','glasn','shipyash']},
 upravl:{t:'Управление',d:'Связь, при которой главное слово требует, чтобы зависимое стояло в определённом падеже. Причастие управляет так же, как глагол, от которого оно образовано.',ex:'читающий (что?) книгу; любующийся (чем?) закатом',cat:'Синтаксис и пунктуация',f:'управлени[а-яё]*',at:'pr1',see:['soglas','perekh','padezh']},
 ustar:{t:'Устаревшее слово',d:'Слово или форма, которые вышли из живого употребления, но иногда сохраняются в образованных от них словах.',ex:'«движить» → движимый',cat:'Общие понятия',f:'устаревш[а-яё]*',at:'',see:['norma','iskl']},
 ustoich:{t:'Устойчивое сочетание',d:'Сочетание слов с цельным значением, которое не составляют каждый раз заново, а берут из языка готовым.',ex:'названый брат, посажёный отец, писаная красавица, Прощёное воскресенье',cat:'Общие понятия',f:'устойчив[а-яё]* сочетани[а-яё]*',at:'nn3',see:['znach','otgl']},
 forma:{t:'Форма слова',d:'Вариант одного и того же слова, который отличается окончанием (иногда суффиксом) и выражает грамматическое значение.',ex:'читающий, читающего, читающими — формы одного причастия',cat:'Морфология',f:'форм[а-яё]* слов(?:а|о)',at:'',see:['okonch','sklon','gram_priznak']},
 chastica:{t:'Частица',d:'Служебная часть речи, которая добавляет слову или предложению оттенок значения: отрицание, вопрос, усиление. Не — отрицательная частица.',ex:'книга не прочитана; вовсе не интересующийся',cat:'Морфология',f:'частиц(?:а|ы|е|у|ей|ами|ам|ах)?',at:'',see:['sluzh','ne_prich','soyuz']},
 chast_rechi:{t:'Часть речи',d:'Большая группа слов с общим значением, общими вопросами и грамматическими признаками. Части речи бывают самостоятельные и служебные.',ex:'существительное, прилагательное, глагол, наречие; предлог, союз, частица',cat:'Морфология',f:'част(?:ь|и|ей|ям|ями|ях) речи',at:'pr1',see:['samost','sluzh','gram_priznak']},
 cheredov:{t:'Чередование',d:'Замена одного звука другим в одной и той же части слова в разных словах или формах.',ex:'бросить — брошенный (с/ш), купить — купленный (п/пл)',cat:'Морфемика и словообразование',f:'чередовани[а-яё]*',at:'',see:['koren','osnova']},
 chislo:{t:'Число',d:'Признак, который показывает, один предмет или несколько. Число бывает единственное и множественное.',ex:'читающий — читающие; книга — книги',cat:'Морфология',f:'(?:единственн|множественн)[а-яё]* числ(?:о|а|у|ом|е)',at:'',see:['rod','padezh','soglas']},
 chlen:{t:'Член предложения',d:'Слово или сочетание слов, которое выполняет в предложении определённую роль. Главные члены — подлежащее и сказуемое, второстепенные — определение, дополнение и обстоятельство.',ex:'Прочитанная (опр.) книга (подл.) лежит (сказ.) на столе (обст.).',cat:'Синтаксис и пунктуация',f:'член[а-яё]* предложени[а-яё]*',at:'',see:['podl','skaz','opred','dop']},
 shipyash:{t:'Шипящие',d:'Согласные ж, ш, ч, щ. После них под ударением пишется о или ё — по правилам главы «О и Ё после шипящих»: в корне ё, если есть слово с е (жёлтый — желтеть); в окончаниях и суффиксах — о (ножом, медвежонок); в словах-действиях и словах от них — ё (жжёт, решённый, тушёнка).',ex:'решённый, сожжённый, испечённый, тушёный, копчёный',cat:'Орфография',f:'шипящ(?:ие|их|им|ими)',at:'sh21',see:['soglasn','udar','suff']},
 norma:{t:'Языковая норма',d:'Принятое в литературном языке правило произношения, написания или употребления слова. Нормы записаны в словарях и справочниках, например в Правилах 2006 года.',ex:'правильно: тот, кто прочитает; ошибка: «прочитающий»',cat:'Общие понятия',f:'языков[а-яё]* норм[а-яё]*|литературн[а-яё]* норм[а-яё]*',at:'',see:['lityaz','orfogr','razgovor']},
 // лексика: глава «Слово и его значение» (leks)
 leksika:{t:'Лексика',d:'Все слова языка, его словарный состав. Раздел науки о языке, который изучает слова и их значения, — лексикология.',ex:'исконные и заимствованные, общеупотребительные и диалектные слова',cat:'Лексика',f:'лексик(?:а|и|е|у|ой)|лексикологи(?:я|и|ю|ей)',at:'lk1',see:['znach','tolk_sl']},
 tolkov:{t:'Толкование',d:'Объяснение лексического значения слова: описанием, близким по смыслу словом, однокоренным или противоположным по смыслу словом. Хорошее толкование можно подставить в предложение вместо слова.',ex:'сугроб — куча снега, наметённая ветром; отважный — смелый; смелость — свойство смелого',cat:'Лексика',f:'толковани(?:е|я|ю|ем|и|й|ям|ями|ях)',at:'lk1',see:['znach','tolk_sl']},
 tolk_sl:{t:'Толковый словарь',d:'Словарь, который объясняет значения слов. Значения многозначного слова даны в одной статье под номерами; пометы показывают переносные, устаревшие, местные слова.',ex:'словари В. И. Даля, Д. Н. Ушакова, С. И. Ожегова',cat:'Лексика',f:'толков(?:ый|ого|ому|ым|ом|ые|ых|ыми) словар[а-яё]*',at:'lk1',see:['slov_st','znach','mnogozn']},
 slov_st:{t:'Словарная статья',d:'Часть словаря, посвящённая одному слову: заглавное слово с ударением, пометы, толкования значений под номерами, примеры, устойчивые сочетания.',ex:'ЗОЛОТО́Й. 1. Сделанный из золота. 2. Цвета золота. 3. перен. Очень хороший.',cat:'Лексика',f:'словарн(?:ая|ой|ую|ые|ых|ым|ыми) стать[а-яё]*',at:'lk1',see:['tolk_sl']},
 kontekst:{t:'Контекст',d:'Окружение слова — соседние слова и предложения. По контексту понятно, в каком значении употреблено многозначное слово.',ex:'часы идут (работают) — дождь идёт (падает)',cat:'Лексика',f:'контекст(?:а|у|ом|е)?',at:'lk1',see:['mnogozn','znach']},
 odnozn:{t:'Однозначное слово',d:'Слово, у которого одно лексическое значение. Обычно это термины и названия узких, конкретных предметов.',ex:'троллейбус, подоконник, бинокль, гипотенуза',cat:'Лексика',f:'однозначн(?:ое|ые|ых|ого|ому|ым|ыми) слов(?:о|а|ам|ами|ах)?',at:'lk2',see:['mnogozn','termin']},
 mnogozn:{t:'Многозначное слово',d:'Слово, у которого два значения и больше, связанные между собой общим признаком. Нужное значение показывает контекст.',ex:'нос человека — нос лодки; часы идут — человек идёт',cat:'Лексика',f:'многозначн(?:ое|ые|ых|ого|ому|ым|ыми) слов(?:о|а|ам|ами|ах)?|многозначност(?:ь|и|ью)',at:'lk2',see:['odnozn','pryam','perenosn','omonim']},
 pryam:{t:'Прямое значение',d:'Основное значение слова: оно прямо называет предмет, признак или действие.',ex:'золотое кольцо, железный гвоздь, нос человека',cat:'Лексика',f:'прям(?:ое|ого|ому|ым|ом) значени[а-яё]*',at:'lk3',see:['perenosn','mnogozn']},
 perenosn:{t:'Переносное значение',d:'Значение, которое появилось, когда название перенесли с одного предмета, признака, действия на другой — по сходству (метафора) или по смежности (метонимия). В словаре — помета «перен.».',ex:'золотые руки, нос лодки, ветер воет, съел тарелку супа',cat:'Лексика',f:'переносн(?:ое|ого|ому|ым|ом|ые|ых|ыми) значени[а-яё]*',at:'lk3',see:['pryam','metafora','metonim']},
 metafora:{t:'Метафора',d:'Перенос названия по сходству: форме, цвету, расположению, назначению, свойствам. Метафору можно развернуть в сравнение с «как».',ex:'шляпка гриба, золотая осень, хвост поезда, железная воля',cat:'Лексика',f:'метафор(?:а|ы|е|у|ой|ами|ах|ам)?|метафорическ[а-яё]*',at:'lk3',see:['perenosn','olicetv','metonim']},
 olicetv:{t:'Олицетворение',d:'Вид метафоры: неживое наделяется свойствами живого — говорит, спит, плачет, сердится.',ex:'ветер злится, лес спит, «Лениво дышит полдень мглистый» (Ф. И. Тютчев)',cat:'Лексика',f:'олицетворени(?:е|я|ю|ем|и|й|ями|ях)',at:'lk3',see:['metafora']},
 metonim:{t:'Метонимия',d:'Перенос названия по смежности — на то, что связано с предметом: посуда — содержимое, место — люди, материал — изделие, автор — произведения.',ex:'съел тарелку супа, весь класс пошёл в музей, читать Пушкина, получил золото',cat:'Лексика',f:'метоними(?:я|и|ю|ей|й|ями)',at:'lk3',see:['perenosn','metafora','sinekdoha']},
 sinekdoha:{t:'Синекдоха',d:'Вид метонимии: целое называют по части или по заметной примете.',ex:'в семье пять ртов; ни одной живой души; светлая голова',cat:'Лексика',f:'синекдох(?:а|и|у|ой|е)',at:'lk3',see:['metonim']},
 iskon:{t:'Исконно русские слова',d:'Слова, которые возникли в русском языке или достались ему от языков-предков (общеславянские, восточнославянские).',ex:'берёза, дом, голова, хороший, зажигалка',cat:'Лексика',f:'исконн(?:о|ые|ых|ое|ого|ым|ыми|ая|ой)(?: русск(?:ие|их|ое|ого|им|ими|ая|ой))?',at:'lk4',see:['zaimstv','staroslav']},
 zaimstv:{t:'Заимствованное слово',d:'Слово, пришедшее из другого языка. Приметы: начальные а и э, буква ф, две гласные подряд, неизменяемость; у многих давних заимствований примет нет.',ex:'тетрадь (греч.), сарафан (тюрк.), галстук (нем.), пальто (франц.), футбол (англ.)',cat:'Лексика',f:'заимствованн(?:ое|ые|ых|ого|ому|ым|ыми|ая|ой) слов[а-яё]*|заимствовани(?:е|я|ю|ем|и|й|ями|ях)',at:'lk4',see:['iskon','staroslav','ekzotizm']},
 staroslav:{t:'Старославянизм',d:'Слово, пришедшее из старославянского языка церковных книг. Примета — сочетания ра, ла, ре, ле на месте русских оро, оло, ере; жд на месте ж; щ на месте ч.',ex:'град — город, злато — золото, брег — берег, чуждый — чужой, освещение — свеча',cat:'Лексика',f:'старославянизм[а-яё]*',at:'lk4',see:['iskon','zaimstv','arhaizm']},
 istorizm:{t:'Историзм',d:'Устаревшее слово, которое называет исчезнувший предмет или явление; современной замены у него нет.',ex:'кафтан, боярин, кольчуга, ямщик, лучина, верста',cat:'Лексика',f:'историзм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',see:['arhaizm','neolog','ustar']},
 arhaizm:{t:'Архаизм',d:'Устаревшее название предмета или явления, которое есть и сейчас, но называется другим словом.',ex:'очи — глаза, чело — лоб, перст — палец, ветрило — парус, брег — берег',cat:'Лексика',f:'архаизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',see:['istorizm','staroslav','ustar']},
 neolog:{t:'Неологизм',d:'Новое слово (или новое значение слова), которое ещё воспринимается как непривычное. Со временем становится обычным.',ex:'в 1960-х — слово космонавт, в 1970 году — луноход; новое значение — спутник (аппарат), мышь (у компьютера)',cat:'Лексика',f:'неологизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',see:['istorizm','zaimstv']},
 ekzotizm:{t:'Экзотизм',d:'Заимствованное слово, которое называет предмет чужой жизни и употребляется только о ней.',ex:'сакля, юрта, кимоно, рикша, вигвам',cat:'Лексика',f:'экзотизм[а-яё]*',at:'lk4',see:['zaimstv']},
 obsheup:{t:'Общеупотребительные слова',d:'Слова, которые знают и употребляют все, кто говорит по-русски. Остальные — слова ограниченного употребления: диалектизмы, термины, профессионализмы, жаргонизмы.',ex:'вода, хлеб, дом, идти, добрый',cat:'Лексика',f:'общеупотребительн(?:ые|ых|ое|ого|ым|ыми|ая|ой)(?: слов[а-яё]*)?',at:'lk5',see:['dialekt','termin','profess','zhargon']},
 dialekt:{t:'Диалектизм',d:'Слово местного говора (диалекта), которое употребляют жители одной местности. В словаре — помета «обл.».',ex:'кочет — петух, векша — белка, гутарить — говорить, умет — постоялый двор',cat:'Лексика',f:'диалектизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?|диалект(?:а|у|ом|е|ы|ов|ам|ах)?',at:'lk5',see:['obsheup','profess','zhargon']},
 termin:{t:'Термин',d:'Официальное точное название понятия науки или техники. Термин однозначен и не несёт оттенка чувства.',ex:'орфограмма, гипотенуза, биссектриса, молекула',cat:'Лексика',f:'термин(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'lk5',see:['profess','odnozn','obsheup']},
 profess:{t:'Профессионализм',d:'Неофициальное, часто образное слово людей одной профессии, которым в живой речи заменяют термин.',ex:'баранка — руль (у шофёров), шкурка — наждачная бумага (у столяров), свеча — резкий подъём температуры на графике (у врачей)',cat:'Лексика',f:'профессионализм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk5',see:['termin','zhargon']},
 zhargon:{t:'Жаргонизм',d:'Слово, которое употребляют в узкой группе людей (школьники, студенты, любители компьютерных игр). В литературной речи неуместно.',ex:'шпора — шпаргалка, физра — физкультура, клава — клавиатура',cat:'Лексика',f:'жаргонизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?|жаргон(?:а|у|ом|е)?',at:'lk5',see:['dialekt','profess','obsheup']},
 sochet:{t:'Лексическая сочетаемость',d:'Способность слов соединяться друг с другом по смыслу. Её нарушение — лексическая ошибка, часто от смешения двух выражений.',ex:'доставить радость, но причинить горе; нанести вред, но оказать помощь',cat:'Лексика',f:'лексическ(?:ая|ой|ую) сочетаемост(?:ь|и|ью)|сочетаемост(?:ь|и|ью)',at:'lk5',see:['pleonazm','tavtol']},
 // фразеология (глава «Фразеологизмы»)
 frazeol:{t:'Фразеологизм',d:'Устойчивое сочетание слов с единым значением, которое не складывается из значений слов. Его употребляют в готовом виде; слова в нём не заменяют. Часто равен по смыслу одному слову.',ex:'бить баклуши — бездельничать; рукой подать — близко; как снег на голову — неожиданно',cat:'Лексика',f:'фразеологизм[а-яё]*|фразеологическ(?:ий|ого|им|ом|ие|их) оборот[а-яё]*',at:'fr1',see:['svob_soch','frazeologia','krylat','poslov']},
 frazeologia:{t:'Фразеология',d:'Все фразеологизмы языка. Раздел науки о языке, который изучает устойчивые обороты: их значение, происхождение и употребление.',ex:'бить баклуши, ахиллесова пята, тришкин кафтан',cat:'Лексика',f:'фразеологи(?:я|и|ю|ей)',at:'fr1',see:['frazeol','leksika']},
 svob_soch:{t:'Свободное сочетание',d:'Сочетание слов, которое говорящий строит сам: каждое слово сохраняет своё значение и может быть заменено другим. Противопоставлено фразеологизму.',ex:'железная лопата, деревянная лопата; сел в лужу (упал) — свободное, сел в лужу (опозорился) — фразеологизм',cat:'Лексика',f:'свободн(?:ое|ого|ым|ом|ые|ых|ыми) сочетани[а-яё]*',at:'fr1',see:['frazeol','kontekst']},
 krylat:{t:'Крылатые слова',d:'Меткие выражения из книг и речей, которые все знают и повторяют: строки писателей, названия произведений, имена героев.',ex:'«А ларчик просто открывался» (И. А. Крылов); «Счастливые часов не наблюдают» (А. С. Грибоедов); у разбитого корыта (А. С. Пушкин)',cat:'Лексика',f:'крылат(?:ые|ых|ым|ыми) слов(?:а|ам|ами|ах)?|крылат(?:ое|ого|ым|ые|ых) выражени[а-яё]*',at:'fr3',see:['frazeol','poslov']},
 poslov:{t:'Пословица',d:'Краткое народное изречение — законченное предложение с поучением, выводом.',ex:'Семь раз отмерь — один раз отрежь. Без труда не вытащишь и рыбку из пруда.',cat:'Лексика',f:'пословиц[а-яё]*',at:'fr4',see:['pogov','frazeol']},
 pogov:{t:'Поговорка',d:'Меткое народное выражение без поучения: оно образно оценивает человека или событие, но вывода не содержит. Граница между поговоркой и фразеологизмом нечёткая.',ex:'Вот тебе, бабушка, и Юрьев день. Лёгок на помине. Чудеса в решете.',cat:'Лексика',f:'поговорк[а-яё]*|поговорок',at:'fr4',see:['poslov','frazeol']},
};
